158	// ─── ELF arch detection ──────────────────────────────────────────────────────
159	
160	static std::string detect_arch(const std::string& path) {
161	  std::ifstream f(path, std::ios::binary);
162	  if (!f) return "";
163	  uint8_t buf[20];
164	  f.read(reinterpret_cast<char*>(buf), 20);
165	  if (!f || buf[0] != 0x7f || buf[1] != 'E' || buf[2] != 'L' || buf[3] != 'F')
166	    return "";
167	  uint16_t e_machine = static_cast<uint16_t>(buf[18]) | (static_cast<uint16_t>(buf[19]) << 8);
168	  if (e_machine != 0xF3) return "";  // not RISC-V (EM_RISCV=243)
169	  return (buf[4] == ELFCLASS64) ? "riscv64" : "riscv32";
170	}
