218	// Write lines to argv's stdin; capture its stdout. Used for addr2line.
219	static std::string capture_with_stdin(const std::vector<std::string>& argv,
220	                                       const std::string& input) {
221	  if (argv.empty()) return "";
222	  int in_fds[2], out_fds[2];
223	  if (pipe(in_fds) != 0) return "";
224	  if (pipe(out_fds) != 0) { close(in_fds[0]); close(in_fds[1]); return ""; }
225	  pid_t pid = fork();
226	  if (pid < 0) {
227	    close(in_fds[0]); close(in_fds[1]);
228	    close(out_fds[0]); close(out_fds[1]);
229	    return "";
230	  }
231	  if (pid == 0) {
232	    close(in_fds[1]); close(out_fds[0]);
233	    dup2(in_fds[0], STDIN_FILENO);
234	    dup2(out_fds[1], STDOUT_FILENO);
235	    int devnull = open("/dev/null", O_WRONLY);
236	    if (devnull >= 0) { dup2(devnull, STDERR_FILENO); if (devnull > 2) close(devnull); }
237	    close(in_fds[0]); close(out_fds[1]);
238	    std::vector<char*> cargv;
239	    cargv.reserve(argv.size() + 1);
240	    for (const auto& a : argv) cargv.push_back(const_cast<char*>(a.c_str()));
241	    cargv.push_back(nullptr);
242	    execvp(cargv[0], cargv.data());
243	    _exit(127);
244	  }
245	  close(in_fds[0]); close(out_fds[1]);
246	  // Write input then close to signal EOF.
247	  const char* p = input.data();
248	  size_t rem = input.size();
249	  while (rem > 0) {
250	    ssize_t w = write(in_fds[1], p, rem);
251	    if (w < 0) break;
252	    p += w; rem -= static_cast<size_t>(w);
253	  }
254	  close(in_fds[1]);
255	  std::string out;
256	  char buf[4096];
257	  ssize_t n;
258	  while ((n = read(out_fds[0], buf, sizeof(buf))) > 0)
259	    out.append(buf, static_cast<size_t>(n));
260	  close(out_fds[0]);
261	  waitpid(pid, nullptr, 0);
262	  return out;
263	}
