265	static bool cmd_exists(const std::string& cmd) {
266	  if (cmd.find('/') != std::string::npos)
267	    return access(cmd.c_str(), X_OK) == 0;
268	  const char* path_env = getenv("PATH");
269	  if (!path_env) return false;
270	  std::istringstream ss(path_env);
271	  std::string dir;
272	  while (std::getline(ss, dir, ':')) {
273	    if (!dir.empty() && access((dir + "/" + cmd).c_str(), X_OK) == 0) return true;
274	  }
275	  return false;
276	}
