420	static std::string src_basename(const std::string& s) {
421	  if (s.empty()) return "";
422	  // "path:line[ (extra)]" -> "basename(path):line[ ...]"
423	  auto sp = s.find(' ');
424	  std::string head = (sp != std::string::npos) ? s.substr(0, sp) : s;
425	  std::string tail = (sp != std::string::npos) ? s.substr(sp) : "";
426	  auto slash = head.rfind('/');
427	  return ((slash != std::string::npos) ? head.substr(slash + 1) : head) + tail;
428	}
429	
430	static std::pair<std::string,int> parse_file_line(const std::string& s) {
431	  if (s.empty() || s.rfind("??", 0) == 0) return {"", 0};
432	  static const std::regex re(R"(^(.+?):(\d+)(?::\d+)?(?:\s|$))");
433	  std::smatch m;
434	  if (!std::regex_search(s, m, re)) return {"", 0};
435	  return {m[1], std::stoi(m[2])};
436	}
437	
438	static std::string read_source_line(const std::string& path, int lineno) {
439	  if (path.empty() || lineno <= 0 || !fs::is_regular_file(path)) return "";
440	  std::ifstream f(path);
441	  std::string line;
442	  for (int i = 1; std::getline(f, line); ++i) {
443	    if (i == lineno) {
444	      while (!line.empty() && (line.back() == '\r' || line.back() == '\n' ||
445	                                line.back() == ' '  || line.back() == '\t'))
446	        line.pop_back();
447	      auto s = line.find_first_not_of(" \t");
448	      return (s != std::string::npos) ? line.substr(s) : line;
449	    }
450	  }
451	  return "";
452	}
