454	// ─── Loop structures + nesting ───────────────────────────────────────────────
455	
456	struct Loop {
457	  std::string id;
458	  uint64_t start, end, iters;
459	  Loop* parent = nullptr;
460	  std::vector<Loop*> children;
461	};
462	
463	static std::vector<Loop> build_loops(
464	    const std::vector<LogEntry>& rows, int limit)
465	{
466	  std::vector<Loop> loops;
467	  int n = std::min(static_cast<int>(rows.size()), limit);
468	  loops.reserve(static_cast<size_t>(n));
469	  for (int i = 0; i < n; ++i)
470	    loops.push_back({"L" + std::to_string(i + 1),
471	                     rows[static_cast<size_t>(i)].start,
472	                     rows[static_cast<size_t>(i)].end,
473	                     rows[static_cast<size_t>(i)].iters,
474	                     nullptr, {}});
475	
476	  // Compute parent: smallest enclosing range.
477	  for (auto& loop : loops) {
478	    Loop* best = nullptr;
479	    uint64_t best_sz = UINT64_MAX;
480	    for (auto& cand : loops) {
481	      if (&cand == &loop) continue;
482	      if (cand.start == loop.start && cand.end == loop.end) continue; // identical
483	      if (cand.start <= loop.start && loop.end <= cand.end) {
484	        uint64_t sz = cand.end - cand.start;
485	        if (sz < best_sz) { best = &cand; best_sz = sz; }
486	      }
487	    }
488	    loop.parent = best;
489	  }
490	  for (auto& loop : loops)
491	    if (loop.parent) loop.parent->children.push_back(&loop);
492	
493	  return loops;
494	}
