496	// ─── Output: table ───────────────────────────────────────────────────────────
497	
498	static std::string src_short(const std::map<uint64_t, std::string>& src_map, uint64_t pc) {
499	  auto it = src_map.find(pc);
500	  return it != src_map.end() ? src_basename(it->second) : "";
501	}
502	
503	static void print_table(
504	    const std::vector<LogEntry>& rows,
505	    const std::string& elf_path,
506	    const std::map<uint64_t, std::string>& src_map,
507	    int min_iters, bool optimize_rvv)
508	{
509	  bool have_src = !src_map.empty();
510	
511	  auto srcpair = [&](uint64_t s, uint64_t e) -> std::string {
512	    std::string a = src_short(src_map, s), b = src_short(src_map, e);
513	    if (!a.empty() && a == b) return a;
514	    return (a.empty() ? "?" : a) + " -> " + (b.empty() ? "?" : b);
515	  };
516	
517	  printf("# hot loops (iters >= %d", min_iters);
518	  if (optimize_rvv) printf(", RVV-only");
519	  printf("), sorted desc, top %zu\n", rows.size());
520	
521	  size_t w_iter = 5;  // strlen("iters")
522	  for (const auto& r : rows) {
523	    char buf[24]; snprintf(buf, sizeof(buf), "%llu", (unsigned long long)r.iters);
524	    w_iter = std::max(w_iter, strlen(buf));
525	  }
526	  const size_t w_pc = 18;
527	  size_t w_sym = 8;  // strlen("location")
528	  for (const auto& r : rows) {
529	    std::string loc = sym_at(elf_path, r.start) + " -> " + sym_at(elf_path, r.end);
530	    w_sym = std::max(w_sym, loc.size());
531	  }
532	
533	  if (have_src) {
534	    printf("%*s | %-*s -> %-*s | %-*s | source\n",
535	           static_cast<int>(w_iter), "iters",
536	           static_cast<int>(w_pc), "start_pc",
537	           static_cast<int>(w_pc), "end_pc",
538	           static_cast<int>(w_sym), "location");
539	  } else {
540	    printf("%*s | %-*s -> %-*s | location\n",
541	           static_cast<int>(w_iter), "iters",
542	           static_cast<int>(w_pc), "start_pc",
543	           static_cast<int>(w_pc), "end_pc");
544	  }
545	  size_t sep = w_iter + 3 + w_pc + 4 + w_pc + 3 + w_sym;
546	  if (have_src) sep += 3 + 12;
547	  printf("%s\n", std::string(sep, '-').c_str());
548	
549	  for (const auto& r : rows) {
550	    std::string loc = sym_at(elf_path, r.start) + " -> " + sym_at(elf_path, r.end);
551	    if (have_src)
552	      printf("%*llu | 0x%016llx -> 0x%016llx | %-*s | %s\n",
553	             static_cast<int>(w_iter), (unsigned long long)r.iters,
554	             (unsigned long long)r.start, (unsigned long long)r.end,
555	             static_cast<int>(w_sym), loc.c_str(),
556	             srcpair(r.start, r.end).c_str());
557	    else
558	      printf("%*llu | 0x%016llx -> 0x%016llx | %s\n",
559	             static_cast<int>(w_iter), (unsigned long long)r.iters,
560	             (unsigned long long)r.start, (unsigned long long)r.end,
561	             loc.c_str());
562	  }
563	}
564	
565	// ─── Output: LLM Markdown ────────────────────────────────────────────────────
566	
567	static void print_llm(
568	    const std::vector<Loop>& loops,
569	    uint64_t total_iters_all,
570	    const std::string& elf_path,
571	    const std::map<uint64_t, std::string>& src_map,
572	    const std::map<uint64_t, InsnInfo>& disasm,
573	    int min_iters, bool optimize_rvv)
574	{
575	  auto pct = [&](uint64_t n) -> double {
576	    return total_iters_all ? 100.0 * n / total_iters_all : 0.0;
577	  };
578	  auto src_full = [&](uint64_t pc) -> std::string {
579	    auto it = src_map.find(pc); return it != src_map.end() ? it->second : "";
580	  };
581	
582	  // Header + TL;DR
583	  {
584	    const auto& top = loops[0];
585	    auto rvv = rvv_in_range(disasm, top.start, top.end);
586	    std::string rvv_str;
587	    if (!rvv.empty()) {
588	      std::vector<std::string> uniq;
589	      for (const auto& r : rvv)
590	        if (std::find(uniq.begin(), uniq.end(), r.mn) == uniq.end())
591	          uniq.push_back(r.mn);
592	      rvv_str = "RVV (";
593	      for (size_t i = 0; i < std::min(uniq.size(), size_t{3}); ++i) {
594	        if (i) rvv_str += ", ";
595	        rvv_str += uniq[i];
596	      }
597	      if (uniq.size() > 3) { rvv_str += ", +" + std::to_string(uniq.size()-3) + " more"; }
598	      rvv_str += ")";
599	    } else {
600	      rvv_str = "scalar";
601	    }
602	    std::string fn = sym_func_at(elf_path, top.start);
603	    std::string src_s = src_short(src_map, top.start); if (src_s.empty()) src_s = "?";
604	    std::string nest_str = top.parent
605	                         ? "nested inside " + top.parent->id
606	                         : "top-level (no parent loop)";
607	    std::string child_str;
608	    if (!top.children.empty()) {
609	      child_str = "and contains " + std::to_string(top.children.size()) + " inner loop(s): ";
610	      for (size_t i = 0; i < top.children.size(); ++i) {
611	        if (i) child_str += ", ";
612	        child_str += top.children[i]->id;
613	      }
614	    } else {
615	      child_str = "and contains no inner loop";
616	    }
617	    printf("# Hotloops Report\n");
618	    printf("target:           %s\n", fs::path(elf_path).filename().c_str());
619	    printf("total_iters:      %llu\n", (unsigned long long)total_iters_all);
620	    printf("reported_loops:   %zu\n", loops.size());
621	    printf("min_iters:        %d\n", min_iters);
622	    printf("rvv_filter:       %s\n", optimize_rvv ? "on" : "off");
623	    printf("\n## TL;DR\n");
624	    printf("Hottest loop is %s in `%s` (%s), %llu iters = %.1f%% of total. "
625	           "Body is %s. It is %s, %s.\n",
626	           top.id.c_str(), fn.c_str(), src_s.c_str(),
627	           (unsigned long long)top.iters, pct(top.iters),
628	           rvv_str.c_str(), nest_str.c_str(), child_str.c_str());
629	    printf("\n## Loops\n");
630	  }
631	
632	  for (size_t idx = 0; idx < loops.size(); ++idx) {
633	    const auto& loop = loops[idx];
634	    printf("\n### %s%s  (%.1f%% of total)\n",
635	           loop.id.c_str(), idx == 0 ? " [hottest]" : "", pct(loop.iters));
636	    printf("iters:        %llu\n", (unsigned long long)loop.iters);
637	    printf("function:     %s -> %s\n",
638	           sym_at(elf_path, loop.start).c_str(),
639	           sym_at(elf_path, loop.end).c_str());
640	
641	    // measure: whole enclosing function (entry -> ret).
642	    auto [fn_entry, fn_end] = andes_sim::fn_range(elf_path, loop.start);
643	    if (fn_entry != 0 && fn_end != 0) {
644	      uint64_t ret_pc = fn_end - 4;  // safe default (standard ret is 4 bytes)
645	      auto it = disasm.lower_bound(fn_end);
646	      if (it != disasm.begin()) { --it; if (it->first >= fn_entry) ret_pc = it->first; }
647	      printf("measure:      --pc-start 0x%llx --pc-end 0x%llx"
648	             "  (all of %s: entry -> ret)\n",
649	             (unsigned long long)fn_entry, (unsigned long long)ret_pc,
650	             sym_func_at(elf_path, loop.start).c_str());
651	    }
652	
653	    std::string sf = src_full(loop.start), se = src_full(loop.end);
654	    if (!sf.empty() && !se.empty() && sf == se)
655	      printf("source:       %s\n", src_basename(sf).c_str());
656	    else
657	      printf("source:       %s -> %s\n",
658	             (sf.empty() ? "?" : src_basename(sf)).c_str(),
659	             (se.empty() ? "?" : src_basename(se)).c_str());
660	
661	    {
662	      auto [path, lineno] = parse_file_line(sf);
663	      std::string snippet = read_source_line(path, lineno);
664	      if (!snippet.empty()) {
665	        if (snippet.size() > 200) snippet = snippet.substr(0, 197) + "...";
666	        printf("code:         %s\n", snippet.c_str());
667	      }
668	    }
669	
670	    auto rvv = rvv_in_range(disasm, loop.start, loop.end);
671	    if (!rvv.empty()) {
672	      printf("rvv:          yes (%zu insn%s)\n", rvv.size(), rvv.size() == 1 ? "" : "s");
673	      printf("rvv_insns:\n");
674	      for (size_t i = 0; i < std::min(rvv.size(), size_t{8}); ++i)
675	        printf("  - 0x%llx  %-10s %s\n",
676	               (unsigned long long)rvv[i].pc, rvv[i].mn.c_str(), rvv[i].ops.c_str());
677	      if (rvv.size() > 8) printf("  - ... (%zu more)\n", rvv.size() - 8);
678	    } else {
679	      printf("rvv:          no\n");
680	    }
681	
682	    printf("parent:       %s\n", loop.parent ? loop.parent->id.c_str() : "-");
683	    if (!loop.children.empty()) {
684	      printf("children:     [");
685	      for (size_t i = 0; i < loop.children.size(); ++i) {
686	        if (i) printf(", ");
687	        printf("%s", loop.children[i]->id.c_str());
688	      }
689	      printf("]\n");
690	    } else {
691	      printf("children:     []\n");
692	    }
693	
694	    auto callees = calls_in_range(disasm, loop.start, loop.end);
695	    if (!callees.empty()) {
696	      printf("calls:\n");
697	      for (size_t i = 0; i < std::min(callees.size(), size_t{8}); ++i)
698	        printf("  - 0x%llx  %s -> %s\n",
699	               (unsigned long long)callees[i].pc,
700	               callees[i].mn.c_str(), callees[i].target.c_str());
701	      if (callees.size() > 8) printf("  - ... (%zu more)\n", callees.size() - 8);
702	    } else {
703	      printf("calls:        []\n");
704	    }
705	  }
706	}
707	
708	// ─── Main ─────────────────────────────────────────────────────────────────────
709	
710	int main(int argc, char** argv) {
711	  Config cfg = parse_args(argc, argv);
712	
713	  // Arch detection.
714	  if (cfg.arch == "auto") {
715	    cfg.arch = detect_arch(cfg.elf);
716	    if (cfg.arch.empty()) {
717	      fprintf(stderr, "error: cannot auto-detect arch (not RISC-V?), pass --arch\n");
718	      return 2;
719	    }
720	  }
721	
722	  // Locate QEMU binary. QEMU is integrated as an external prebuilt binary:
723	  // QEMU_BIN_DIR (config.env, exported by setup.sh) holds qemu-system-{arch}.
724	  if (cfg.qemu.empty()) {
725	    if (const char* dir = std::getenv("QEMU_BIN_DIR"); dir && *dir) {
726	      cfg.qemu = std::string(dir) + "/qemu-system-" + cfg.arch;
727	    } else {
728	      try {
729	        cfg.qemu = (andes_sim::repo_root() / "build" / "qemu" /
730	                    ("qemu-system-" + cfg.arch)).string();
731	      } catch (...) {
732	        cfg.qemu = "qemu-system-" + cfg.arch;
733	      }
734	    }
735	  }
736	  if (!fs::is_regular_file(cfg.qemu) || access(cfg.qemu.c_str(), X_OK) != 0) {
737	    fprintf(stderr, "error: qemu not found/executable: %s\n", cfg.qemu.c_str());
738	    return 2;
739	  }
740	
741	  // Locate hotloops plugin (built by `make -C qemu_plugin`).
742	  if (cfg.plugin.empty()) {
743	    try {
744	      cfg.plugin = (andes_sim::repo_root() / "qemu_plugin" /
745	                    "libhotloops.so").string();
746	    } catch (...) {}
747	  }
748	  if (!fs::is_regular_file(cfg.plugin)) {
749	    fprintf(stderr, "error: plugin not built: %s\n", cfg.plugin.c_str());
750	    return 2;
751	  }
752	
753	  // Temp log file.
754	  TempFile log_file;
755	
756	  // Build QEMU command.
757	  std::string plugin_arg = cfg.plugin +
758	                           ",limit=" + std::to_string(cfg.limit) +
759	                           ",min_iters=" + std::to_string(cfg.min_iters);
760	  std::vector<std::string> qemu_cmd = {
761	    cfg.qemu,
762	    "-plugin", plugin_arg,
763	    "-d", "plugin", "-D", log_file.path,
764	    "-M", cfg.machine,
765	    "-cpu", cfg.cpu,
766	    "-nographic", "-semihosting",
767	    "-bios", cfg.elf
768	  };
769	  if (!cfg.qemu_config.empty()) { qemu_cmd.push_back("-readconfig"); qemu_cmd.push_back(cfg.qemu_config); }
770	  for (const auto& a : cfg.extra_qemu_args) qemu_cmd.push_back(a);
771	
772	  run_silent(qemu_cmd, cfg.qemu_cwd);
773	
774	  // --raw: dump log and exit.
775	  if (cfg.raw) {
776	    std::ifstream f(log_file.path);
777	    std::cout << f.rdbuf();
778	    return 0;
779	  }
780	
781	  // Parse log.
782	  auto rows = parse_log(log_file.path);
783	  if (rows.empty()) {
784	    fprintf(stderr, "hotloops: no backward edges observed\n");
785	    return 0;
786	  }
787	  uint64_t total_iters_all = 0;
788	  for (const auto& r : rows) total_iters_all += r.iters;
789	
790	  // Locate objdump. Prefer the cross objdump from $HYBRID_TOOLCHAIN so that
791	  // RISC-V vendor extensions (RVV, Andes custom) are decoded correctly.
792	  // Generic llvm-objdump on old distros (e.g. LLVM 14) may not support RVV.
793	  if (cfg.objdump.empty()) {
794	    // Resolve HYBRID_TOOLCHAIN: env var first, then config.env in repo root.
795	    std::string hybrid_tc;
796	    if (const char* tc = std::getenv("HYBRID_TOOLCHAIN"); tc && *tc) {
797	      hybrid_tc = tc;
798	    } else {
799	      try {
800	        std::ifstream cenv(andes_sim::repo_root() / "config.env");
801	        std::string line;
802	        while (std::getline(cenv, line)) {
803	          auto eq = line.find('=');
804	          if (eq == std::string::npos) continue;
805	          if (line.substr(0, eq) == "HYBRID_TOOLCHAIN")
806	            hybrid_tc = line.substr(eq + 1);
807	        }
808	      } catch (...) {}
809	    }
810	    std::vector<std::string> cands;
811	    if (!hybrid_tc.empty()) {
812	      std::string tcbin = hybrid_tc + "/bin/";
813	      cands.push_back(tcbin + "riscv64-unknown-elf-objdump");
814	      cands.push_back(tcbin + "riscv32-unknown-elf-objdump");
815	    }
816	    cands.insert(cands.end(), {"riscv64-unknown-elf-objdump",
817	                               "riscv32-unknown-elf-objdump",
818	                               "llvm-objdump", "objdump"});
819	    cfg.objdump = find_first(cands);
820	  }
821	
822	  // Build disassembly map (needed for RVV filter and --llm).
823	  std::map<uint64_t, InsnInfo> disasm;
824	  if (!cfg.objdump.empty() && (cfg.optimize_rvv || cfg.llm)) {
825	    std::string raw = andes_sim::run_process(
826	      {cfg.objdump, "-d", "--no-show-raw-insn", cfg.elf}, 60000).out;
827	    disasm = parse_disasm(raw);
828	  }
829	
830	  // Filter rows.
831	  rows.erase(std::remove_if(rows.begin(), rows.end(),
832	    [&](const LogEntry& r){ return static_cast<int>(r.iters) < cfg.min_iters; }),
833	    rows.end());
834	  if (cfg.optimize_rvv) {
835	    rows.erase(std::remove_if(rows.begin(), rows.end(),
836	      [&](const LogEntry& r){ return rvv_in_range(disasm, r.start, r.end).empty(); }),
837	      rows.end());
838	  }
839	  std::sort(rows.begin(), rows.end(),
840	            [](const LogEntry& a, const LogEntry& b){ return a.iters > b.iters; });
841	  if (static_cast<int>(rows.size()) > cfg.limit)
842	    rows.resize(static_cast<size_t>(cfg.limit));
843	
844	  if (rows.empty()) {
845	    fprintf(stderr, "hotloops: no loops with iters >= %d%s\n",
846	            cfg.min_iters, cfg.optimize_rvv ? " containing RVV instructions" : "");
847	    return 0;
848	  }
849	
850	  // Source line resolution.
851	  std::map<uint64_t, std::string> src_map;
852	  if (!cfg.no_source) {
853	    if (cfg.addr2line_bin.empty())
854	      cfg.addr2line_bin = find_first({"llvm-addr2line", "addr2line",
855	                                      "riscv64-unknown-elf-addr2line",
856	                                      "riscv32-unknown-elf-addr2line",
857	                                      "riscv64-linux-gnu-addr2line"});
858	    if (!cfg.addr2line_bin.empty()) {
859	      // Collect unique PCs from all rows.
860	      std::vector<uint64_t> pcs;
861	      for (const auto& r : rows) {
862	        pcs.push_back(r.start);
863	        pcs.push_back(r.end);
864	      }
865	      std::sort(pcs.begin(), pcs.end());
866	      pcs.erase(std::unique(pcs.begin(), pcs.end()), pcs.end());
867	      src_map = resolve_sources(cfg.addr2line_bin, cfg.elf, pcs);
868	    }
869	  }
870	
871	  // Output.
872	  if (cfg.llm) {
873	    auto loops = build_loops(rows, cfg.limit);
874	    print_llm(loops, total_iters_all, cfg.elf, src_map, disasm,
875	              cfg.min_iters, cfg.optimize_rvv);
876	  } else {
877	    print_table(rows, cfg.elf, src_map, cfg.min_iters, cfg.optimize_rvv);
878	  }
879	  return 0;
880	}
