70	// Validate the lone-ELF positional shape the standalone models require: print
71	// the diagnostic and return 2 on a violation, else 0. Split out so `cycle`
72	// can reject a missing/extra ELF BEFORE paying for engine discovery (which
73	// spawns a --describe subprocess per Verilator build). `model` labels the error.
74	int check_one_elf(const Cli& cli, const char* model) {
75	  if (cli.positional.empty()) {
76	    std::fprintf(stderr,
77	                 "andesim run --mode %s: missing ELF (the workload to run; "
78	                 "e.g. a tests/fixtures/<name>.elf)\n",
79	                 model);
80	    return 2;
81	  }
82	  if (cli.positional.size() > 1) {
83	    std::fprintf(stderr,
84	                 "andesim run --mode %s: unexpected argument '%s' "
85	                 "(engine args go after --)\n",
86	                 model, cli.positional[1].c_str());
87	    return 2;
88	  }
89	  return 0;
90	}
