92	// Reject an ELF whose class width (rv32/rv64) does not match the engine it would
93	// run on -- a clear pre-flight error instead of a cryptic "not of ELFCLASSxx"
94	// from deep inside the engine. Both directions. Returns "" when they agree, when
95	// the ELF is unreadable/not-ELF (reported elsewhere), or when the engine
96	// declares no xlen (cannot judge). Shared by cycle and hybrid: one wording.
97	std::string elf_engine_arch_error(const std::string& elf,
98	                                  const EngineDescriptor& eng) {
99	  const int ex = elf_xlen(elf);
100	  if (ex == 0 || eng.xlen == 0 || ex == eng.xlen) return "";
101	  char buf[256];
102	  std::snprintf(buf, sizeof(buf),
103	                "ELF is rv%d but engine '%s' is rv%ld -- pick a matching engine "
104	                "or an rv%d ELF",
105	                ex, eng.id.c_str(), eng.xlen, ex);
106	  return buf;
107	}
