125	// `run --mode cycle` presentation: spawn the engine, hiding its startup banner
126	// and verbose [info] log (VsimFilter), relaying only the program's own output
127	// and any real diagnostics, then restate the lifted cycle count as andesim's own
128	// one-line result under the [andesim] prefix. The count is printed AFTER the run
129	// (the engine logs it at exit), so it follows the program output. Returns the
130	// engine exit code. Unlike fast's exec_passthrough, the parent stays alive to
131	// filter -- fine, because cycle (without --gdb) is a batch run, not interactive.
132	int run_cycle_clean(const std::vector<std::string>& argv) {
133	  VsimFilter filter;
134	  const int rc = run_line_filtered(
135	      argv, [&filter](int stream, std::string_view line) {
136	        std::FILE* dst = nullptr;
137	        switch (filter.classify(stream, line)) {
138	          case VsimFilter::Dest::kStdout: dst = stdout; break;
139	          case VsimFilter::Dest::kStderr: dst = stderr; break;
140	          case VsimFilter::Dest::kDrop: return;
141	        }
142	        std::fwrite(line.data(), 1, line.size(), dst);
143	        std::fputc('\n', dst);
144	      });
145	  if (const std::optional<uint64_t> c = filter.cycles())
146	    log_result(kLogInfo, "[andesim] %llu cycles",
147	               static_cast<unsigned long long>(*c));
148	  return rc;
149	}
