188	// `run --mode fast`: QEMU alone, functional, transparent passthrough. Needs
189	// only the built-in qemu descriptor, so it resolves that directly rather than
190	// discover_engines(), which would spawn a --describe subprocess per Verilator
191	// build only to discard them all here.
192	int run_fast(const Cli& cli) {
193	  // fast is QEMU-only; an explicit engine must name 'qemu64' (rv64) or 'qemu32'.
194	  if (!cli.engine.empty() && cli.engine != kQemuId64 && cli.engine != kQemuId32) {
195	    std::fprintf(stderr,
196	                 "andesim run --mode fast: engine must be 'qemu64' or 'qemu32', "
197	                 "got '%s'\n",
198	                 cli.engine.c_str());
199	    return 2;
200	  }
201	  // --mem-size forwards a plain `-m`; QEMU validates it (as-is, no mmap, no
202	  // default injected). It precedes the post-`--` args, so a user's own -m wins.
203	  std::string err;
204	  std::vector<std::string> extra = qemu_m_args(cli.mem_size, err);
205	  if (!err.empty()) {
206	    std::fprintf(stderr, "andesim run --mode fast: %s\n", err.c_str());
207	    return 2;
208	  }
209	  // --gdb: inject QEMU's built-in GDB stub and pause at startup.
210	  if (cli.gdb) {
211	    const std::string port = cli.gdb_port.empty() ? "1234" : cli.gdb_port;
212	    extra.push_back("-gdb");
213	    extra.push_back("tcp::" + port);
214	    extra.push_back("-S");
215	  }
216	  // Pick rv32 vs rv64. An explicit --engine (qemu32/qemu64) wins; otherwise read
217	  // the ELF's class so an rv32 program lands on qemu-system-riscv32 instead of
218	  // the rv64 default. Warn (do not fail) if an explicit choice contradicts the
219	  // ELF -- the override is the user's call.
220	  const int elf_w = cli.positional.empty() ? 0 : elf_xlen(cli.positional[0]);
221	  int xlen;
222	  if (cli.engine == kQemuId32) xlen = 32;
223	  else if (cli.engine == kQemuId64) xlen = 64;
224	  else xlen = elf_w ? elf_w : 64;  // no explicit engine: follow the ELF (else rv64)
225	  // Only an explicit engine can disagree with the ELF (when none is given, xlen
226	  // == elf_w), so this guard already implies an explicit --engine.
227	  if (elf_w && elf_w != xlen)
228	    std::fprintf(stderr,
229	                 "[andesim] --mode fast: --engine %s is rv%d but the ELF is rv%d "
230	                 "(running as rv%d)\n",
231	                 cli.engine.c_str(), xlen, elf_w, xlen);
232	  return run_standalone(cli, builtin_qemu_arch(xlen), "fast", extra);
233	}
