235	// Block until 127.0.0.1:`port` is LISTENing (or `timeout_ms` elapses). vsim opens
236	// its --jtag-port only after it has reset and halted the hart, so the debugger we
237	// exec next must not race ahead of it -- OpenOCD/ICEman do not retry the bitbang
238	// connect, and a missed connect leaves the session dead. Non-intrusive: scans
239	// /proc/net/tcp rather than connecting (a probe connection would land in vsim's
240	// single debugger slot). Returns false on timeout.
241	static bool wait_for_jtag_port(uint16_t port, int timeout_ms = 20000) {
242	  constexpr int kPollMs = 50;
243	  for (int waited = 0; waited <= timeout_ms; waited += kPollMs) {
244	    if (std::FILE* f = std::fopen("/proc/net/tcp", "re")) {
245	      char line[512];
246	      while (std::fgets(line, sizeof line, f)) {
247	        // cols: sl  local_address(IP:port hex)  rem_address  st  ...
248	        // "%*8x:%x" skips the 8-hex-digit IPv4 and reads the local port; the
249	        // 0A (TCP_LISTEN) filter also drops the non-hex header row.
250	        unsigned lport = 0, st = 0;
251	        if (std::sscanf(line, "%*s %*8x:%x %*s %x", &lport, &st) == 2
252	            && st == 0x0A && lport == port) {
253	          std::fclose(f);
254	          return true;
255	        }
256	      }
257	      std::fclose(f);
258	    }
259	    std::this_thread::sleep_for(std::chrono::milliseconds(kPollMs));
260	  }
261	  return false;
262	}
