264	// `run --mode cycle --gdb`: start vsim with --jtag-port 9104 in the background
265	// (the hart free-runs; ICEman halts it over the JTAG DTM on connect), then exec
266	// ICEman ($ICEMAN env var) with `-Z v5 -I virtual_dmi.cfg` in the foreground.
267	int run_cycle_gdb(const Cli& cli, const EngineDescriptor& eng) {
268	  const char* iceman = std::getenv("ICEMAN");
269	  if (!iceman || !*iceman) {
270	    std::fprintf(stderr,
271	                 "andesim run --mode cycle --gdb: $ICEMAN not set "
272	                 "(export ICEMAN=<path to ICEman binary>)\n");
273	    return 2;
274	  }
275	  // Build vsim argv from the standalone template, appending user passthrough
276	  // and the JTAG port flag.
277	  const std::string elf = abs_elf(cli.positional[0], "--mode cycle --gdb");
278	  if (elf.empty()) return 2;
279	  const std::string jtag_port = cli.gdb_port.empty() ? "9104" : cli.gdb_port;
280	  std::vector<std::string> vsim_pass = cli.passthrough;
281	  vsim_pass.push_back("--jtag-port");
282	  vsim_pass.push_back(jtag_port);
283	  std::string err;
284	  const std::vector<std::string> vsim_argv =
285	      passthrough_argv(eng, "standalone", elf, vsim_pass, err);
286	  if (!err.empty()) {
287	    std::fprintf(stderr, "andesim run --mode cycle --gdb: %s\n", err.c_str());
288	    return 2;
289	  }
290	  std::fprintf(stderr,
291	               "[andesim] --gdb: vsim JTAG on port %s, exec ICEman\n",
292	               jtag_port.c_str());
293	  if (fork_background(vsim_argv) < 0) {
294	    std::fprintf(stderr,
295	                 "andesim run --mode cycle --gdb: failed to fork vsim\n");
296	    return 1;
297	  }
298	  // vsim opens the JTAG port and the hart free-runs; ICEman halts it on connect.
299	  // Wait for the port to be LISTENing before launching the debugger (it does not
300	  // retry the bitbang connect). Numeric ports only; a non-numeric --gdb-port
301	  // (atoi -> 0) skips the wait and lets the engine reject it. Best-effort: warn
302	  // but launch anyway if it never appears.
303	  if (const int pnum = std::atoi(jtag_port.c_str());
304	      pnum > 0 && !wait_for_jtag_port(static_cast<uint16_t>(pnum)))
305	    std::fprintf(stderr,
306	                 "[andesim] --gdb: warning: vsim JTAG port %s not LISTENing "
307	                 "after 20s; launching the debugger anyway\n",
308	                 jtag_port.c_str());
309	  // -I virtual_dmi.cfg selects ICEman's remote_bitbang interface (host
310	  // localhost, port 9104) instead of its default real-hardware adapter; without
311	  // it ICEman finds no adapter and exits. The cfg is found relative to the cwd
312	  // (repo root) in interface/; it pins port 9104, matching --jtag-port's default.
313	  return exec_passthrough({iceman, "-Z", "v5", "-I", "virtual_dmi.cfg"});
314	}
