316	// `run --mode cycle`: one cycle-accurate engine alone, from reset (no QEMU,
317	// no --resume-from-qemu), transparent passthrough -- cycles surface in the
318	// engine's own output. Unlike fast, this must discover the Verilator build(s)
319	// to resolve the engine (explicit --engine, else the sole one).
320	int run_accurate(const Cli& cli) {
321	  // Reject a missing/extra ELF before discovery so a CLI typo does not spawn a
322	  // --describe subprocess per Verilator build only to fail on the argument.
323	  if (int rc = check_one_elf(cli, "cycle")) return rc;
324	  // --mem-size is validated but has nothing to size: the cycle engine always
325	  // models its full DRAM window. Say so instead of silently ignoring it.
326	  if (!cli.mem_size.empty()) {
327	    std::string se;
328	    if (parse_size(cli.mem_size, se); !se.empty()) {
329	      std::fprintf(stderr, "andesim run --mode cycle: --mem-size: %s\n",
330	                   se.c_str());
331	      return 2;
332	    }
333	    log_line(kLogWarn,
334	             "[andesim] --mem-size: the cycle engine models its full "
335	             "DRAM window; nothing to size");
336	  }
337	  Discovery disc = discover_engines();
338	  std::string err;
339	  const EngineDescriptor* eng =
340	      resolve_accurate_engine(disc.engines, cli.engine, err);
341	  if (!eng) {
342	    std::fprintf(stderr, "andesim run --mode cycle: %s\n", err.c_str());
343	    // Surface why an expected engine may be absent (failed --describe, etc.).
344	    for (const std::string& w : disc.warnings)
345	      std::fprintf(stderr, "andesim: skipped engine: %s\n", w.c_str());
346	    return 2;
347	  }
348	  // The ELF must match the engine's width: an rv32 ELF on an rv64 engine (or
349	  // vice versa) cannot run. Catch it here with a clear message instead of the
350	  // engine's cryptic "not of ELFCLASSxx". check_one_elf above guaranteed a lone
351	  // positional.
352	  if (std::string e = elf_engine_arch_error(cli.positional[0], *eng); !e.empty()) {
353	    std::fprintf(stderr, "andesim run --mode cycle: %s\n", e.c_str());
354	    return 2;
355	  }
356	  // --dry-run previews the standalone command and spawns nothing, so it takes
357	  // precedence over the interactive --gdb path (a dry run launches no debugger).
358	  if (cli.gdb && !cli.dry_run) return run_cycle_gdb(cli, *eng);
359	  // clean_output: hide vsim's banner + [info] log, restate the cycle count under
360	  // [andesim] (fast keeps raw passthrough -- QEMU has no such banner and its
361	  // monitor/gdbstub are interactive).
362	  return run_standalone(cli, *eng, "cycle", /*extra=*/{}, /*clean_output=*/true);
363	}
