/*
 * Hot-loop detector plugin.
 *
 * Detects loops by observing backward TB transitions: when the next
 * executed translation block starts at a PC strictly less than the
 * last instruction PC of the previously executed TB, we treat that
 * pair (header_pc=current_tb_start, tail_pc=last_insn_of_prev_tb) as
 * a loop edge and bump its iteration count.
 *
 * Output (at exit, sorted by iteration count desc):
 *   start_pc, end_pc, iterations
 *
 * Copyright (C) 2026
 * License: GNU GPL, version 2 or later.
 *   See the COPYING file in the top-level directory.
 */
#include <inttypes.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <glib.h>

#include <qemu-plugin.h>

QEMU_PLUGIN_EXPORT int qemu_plugin_version = QEMU_PLUGIN_VERSION;

static GMutex lock;              /* guards the shared loops table only */
static GHashTable *loops;        /* key: (start<<1)^end -> LoopEdge* */
static struct qemu_plugin_scoreboard *vcpu_sb;  /* per-cpu VCPUState */
static guint64 limit = 50;       /* max rows printed */
static guint64 min_iters = 1;    /* rows with count < min_iters are dropped */

typedef struct {
    uint64_t start_pc;           /* loop header (target of backward branch) */
    uint64_t end_pc;             /* tail: last insn pc of preceding TB */
    uint64_t count;              /* iterations observed */
} LoopEdge;

typedef struct {
    uint64_t last_tail_pc;       /* PC of last insn of previously executed TB */
    bool     valid;
} VCPUState;

typedef struct {
    uint64_t tb_start;
    uint64_t tb_last_insn_pc;
} TBInfo;

static guint loop_hash(gconstpointer p)
{
    const LoopEdge *e = p;
    return (guint)(e->start_pc * 1315423911u ^ e->end_pc);
}

static gboolean loop_equal(gconstpointer a, gconstpointer b)
{
    const LoopEdge *x = a, *y = b;
    return x->start_pc == y->start_pc && x->end_pc == y->end_pc;
}

static gint cmp_count_desc(gconstpointer a, gconstpointer b)
{
    const LoopEdge *x = a, *y = b;
    if (x->count == y->count) {
        return 0;
    }
    return x->count > y->count ? -1 : 1;
}

static void vcpu_tb_exec(unsigned int cpu_index, void *udata)
{
    TBInfo *tbi = (TBInfo *)udata;
    VCPUState *st = qemu_plugin_scoreboard_find(vcpu_sb, cpu_index);

    if (st->valid && tbi->tb_start <= st->last_tail_pc) {
        LoopEdge probe = {
            .start_pc = tbi->tb_start,
            .end_pc   = st->last_tail_pc,
        };
        g_mutex_lock(&lock);
        LoopEdge *e = g_hash_table_lookup(loops, &probe);
        if (!e) {
            e = g_new0(LoopEdge, 1);
            e->start_pc = probe.start_pc;
            e->end_pc   = probe.end_pc;
            g_hash_table_insert(loops, e, e);
        }
        e->count++;
        g_mutex_unlock(&lock);
    }

    st->last_tail_pc = tbi->tb_last_insn_pc;
    st->valid = true;
}

static void vcpu_tb_trans(G_GNUC_UNUSED qemu_plugin_id_t id,
                          struct qemu_plugin_tb *tb)
{
    size_t n = qemu_plugin_tb_n_insns(tb);
    if (n == 0) {
        return;
    }
    struct qemu_plugin_insn *last = qemu_plugin_tb_get_insn(tb, n - 1);

    TBInfo *tbi = g_new0(TBInfo, 1);
    tbi->tb_start = qemu_plugin_tb_vaddr(tb);
    tbi->tb_last_insn_pc = qemu_plugin_insn_vaddr(last);

    qemu_plugin_register_vcpu_tb_exec_cb(tb, vcpu_tb_exec,
                                         QEMU_PLUGIN_CB_NO_REGS,
                                         (void *)tbi);
}

static void plugin_exit(G_GNUC_UNUSED qemu_plugin_id_t id, G_GNUC_UNUSED void *p)
{
    g_autoptr(GString) report = g_string_new("");
    GList *vals = g_hash_table_get_values(loops);
    vals = g_list_sort(vals, cmp_count_desc);

    guint hot = 0;
    for (GList *it = vals; it; it = it->next) {
        LoopEdge *e = it->data;
        if (e->count >= min_iters) {
            hot++;
        }
    }

    g_string_append_printf(report,
        "hotloops: %u distinct backward edges, %u hot (>= %" PRIu64
        " iters), sorted by iterations desc\n",
        g_hash_table_size(loops), hot, min_iters);
    g_string_append_printf(report, "start_pc, end_pc, iterations\n");

    guint64 i = 0;
    for (GList *it = vals; it && i < limit; it = it->next) {
        LoopEdge *e = it->data;
        if (e->count < min_iters) {
            continue;
        }
        g_string_append_printf(report,
            "0x%016" PRIx64 ", 0x%016" PRIx64 ", %" PRIu64 "\n",
            e->start_pc, e->end_pc, e->count);
        i++;
    }

    qemu_plugin_outs(report->str);

    g_list_free(vals);
    g_hash_table_destroy(loops);
    qemu_plugin_scoreboard_free(vcpu_sb);
}

QEMU_PLUGIN_EXPORT
int qemu_plugin_install(qemu_plugin_id_t id, G_GNUC_UNUSED const qemu_info_t *info,
                        int argc, char **argv)
{
    for (int i = 0; i < argc; i++) {
        char *opt = argv[i];
        g_auto(GStrv) tok = g_strsplit(opt, "=", 2);
        if (g_strcmp0(tok[0], "limit") == 0 && tok[1]) {
            limit = g_ascii_strtoull(tok[1], NULL, 0);
        } else if (g_strcmp0(tok[0], "min_iters") == 0 && tok[1]) {
            min_iters = g_ascii_strtoull(tok[1], NULL, 0);
            if (min_iters == 0) {
                min_iters = 1;
            }
        } else {
            fprintf(stderr, "hotloops: unknown option: %s\n", opt);
            return -1;
        }
    }

    loops = g_hash_table_new_full(loop_hash, loop_equal, NULL, g_free);
    vcpu_sb = qemu_plugin_scoreboard_new(sizeof(VCPUState));

    qemu_plugin_register_vcpu_tb_trans_cb(id, vcpu_tb_trans);
    qemu_plugin_register_atexit_cb(id, plugin_exit, NULL);
    return 0;
}

#!/usr/bin/env bash
# build/hotloops LLM report contract: each loop block carries a ready hybrid
# pc window, `measure: --pc-start 0x<entry> --pc-end 0x<ret>`, derived from
# the loop's enclosing function (one-shot pc triggers fire on the first hit,
# so the function span covers every iteration and needs no objdump step).
#
# Invokes the tool WITHOUT --plugin so the default plugin path
# (qemu_plugin/libhotloops.so) is exercised end-to-end.
#
# Builds a tiny single-ret RVV kernel (vplat runtime), runs the detector,
# and checks the measure line against the toolchain's own nm/objdump as
# the oracle.

set -uo pipefail

SCRIPT_DIR=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)
ROOT=$(cd -- "$SCRIPT_DIR/../.." && pwd)

. "$ROOT/config.env" 2>/dev/null || true
QEMU_BIN="${VSIM_QEMU:-${QEMU_BIN_DIR:-}/qemu-system-riscv64}"
GCC="${HYBRID_TOOLCHAIN:-}/bin/riscv64-unknown-elf-gcc"
NM="${HYBRID_TOOLCHAIN:-}/bin/riscv64-unknown-elf-nm"
OBJDUMP="${HYBRID_TOOLCHAIN:-}/bin/riscv64-unknown-elf-objdump"
HOTLOOPS="$ROOT/build/hotloops"

[ -x "$QEMU_BIN" ] || { echo "SKIP: external qemu not found (source ./setup.sh)"; exit 0; }
[ -f "$ROOT/qemu_plugin/libhotloops.so" ] || { echo "SKIP: hotloops plugin not built (make -C qemu_plugin)"; exit 0; }
[ -x "$GCC" ] || { echo "SKIP: no riscv toolchain"; exit 0; }
[ -d "$ROOT/build/runtime" ] || { echo "SKIP: vplat runtime not built"; exit 0; }
[ -x "$HOTLOOPS" ] || bash "$ROOT/scripts/build_driver.sh" >/dev/null 2>&1
[ -x "$HOTLOOPS" ] || { echo "FAIL[hotloops_measure]: build/hotloops missing"; exit 1; }

TMP=$(mktemp -d -t hotloops-measure.XXXXXX)
trap 'rm -rf "$TMP"' EXIT

cat > "$TMP/vadd.c" <<'EOF'
#include <stdint.h>
#include <riscv_vector.h>
static int32_t a[64], b[64];
__attribute__((noinline)) static void vadd_kernel(void)
{
  for (int r = 0; r < 50; r++)
    for (int i = 0; i < 64;) {
      size_t vl = __riscv_vsetvl_e32m1((size_t) (64 - i));
      vint32m1_t va = __riscv_vle32_v_i32m1(&a[i], vl);
      vint32m1_t vb = __riscv_vle32_v_i32m1(&b[i], vl);
      __riscv_vse32_v_i32m1(&a[i], __riscv_vadd_vv_i32m1(va, vb, vl), vl);
      i += (int) vl;
    }
}
int main(void) { vadd_kernel(); return 0; }
EOF

"$GCC" -march=rv64gcv -mabi=lp64d -O1 \
  -B "$ROOT/build/runtime" -specs=andesim.specs \
  "$TMP/vadd.c" -o "$TMP/vadd.elf" \
  || { echo "FAIL[hotloops_measure]: fixture build failed"; exit 1; }

# NO --plugin: the tool must resolve qemu_plugin/libhotloops.so itself.
REPORT=$("$HOTLOOPS" \
           --qemu "$QEMU_BIN" \
           --cpu "andes-ax45mpv,vext_spec=v1.0,vlen=512" \
           --min-iters 10 "$TMP/vadd.elf" 2>/dev/null)

echo "$REPORT" | grep -q "\[hottest\]" \
  || { echo "FAIL[hotloops_measure]: no hottest loop reported"; echo "$REPORT"; exit 1; }

MEASURE=$(echo "$REPORT" | grep -m1 "^measure:")
[ -n "$MEASURE" ] \
  || { echo "FAIL[hotloops_measure]: no measure: line in the report"; echo "$REPORT"; exit 1; }

GOT_S=$(echo "$MEASURE" | grep -o -- "--pc-start 0x[0-9a-f]*" | awk '{print $2}')
GOT_E=$(echo "$MEASURE" | grep -o -- "--pc-end 0x[0-9a-f]*" | awk '{print $2}')

# Oracle: the kernel's entry from nm; its return = the function's last
# instruction (single-epilogue at -O1; objdump flavors disagree on the
# `ret` vs `c.jr ra` spelling, so match by position, not mnemonic).
WANT_S=$(printf '0x%x' "0x$("$NM" "$TMP/vadd.elf" | awk '$3=="vadd_kernel"{print $1; exit}')")
WANT_E=$(printf '0x%x' "0x$("$OBJDUMP" -d "$TMP/vadd.elf" \
  | sed -n '/<vadd_kernel>:/,/^$/p' | grep -E '^[ ]+[0-9a-f]+:' \
  | tail -1 | awk '{sub(":","",$1); print $1}')")

if [ "$GOT_S" != "$WANT_S" ] || [ "$GOT_E" != "$WANT_E" ]; then
  echo "FAIL[hotloops_measure]: window $GOT_S..$GOT_E, want $WANT_S..$WANT_E"
  echo "$MEASURE"
  exit 1
fi

echo "PASS[hotloops_measure]: measure = $GOT_S .. $GOT_E (all of vadd_kernel), default plugin path OK"

