1	// Unit tests for the pure cores of `run` (no spawn):
2	//   - passthrough_argv (F7): fill an engine's role invoke template ({bin}/{elf})
3	//     then append the verbatim post-`--` engine args -- the data path behind
4	//     `run --mode fast prog.elf -- -gdb tcp::1234 -S` behaving like raw QEMU.
5	//   - resolve_accurate_engine (F8): pick the cycle-accurate engine for
6	//     `run --mode cycle` (explicit --engine or the sole default; the
7	//     ambiguous / missing / wrong-kind error branches).
8	//
9	// The live spawn paths (fast's exec_passthrough, cycle's run_cycle_clean) are
10	// exercised end-to-end by tests/andes_sim/test_andes_sim_f{7,8}.sh;
11	// exec_passthrough's stdio-inherit + exit-code propagation is already covered by
12	// the F5 infra test, so this file stays pure. Plain assert-and-count harness.
13	#include <string>
14	#include <vector>
15	
16	#include "engine_descriptor.hpp"
17	#include "engine_registry.hpp"
18	#include "run_passthrough.hpp"
19	#include "test_check.hpp"
20	
21	using namespace andes_sim;
22	using andes_sim::test::check_eq;
23	
24	namespace {
25	
26	// The standalone template the built-in qemu descriptor ships (engine_registry):
27	// the andes functional config, {bin}/{elf} to be filled.
28	EngineDescriptor fake_qemu() {
29	  EngineDescriptor d;
30	  d.id = "qemu";
31	  d.bin_path = "/q";
32	  d.invoke.push_back(
33	      {"standalone",
34	       {"{bin}", "-machine", "andes_ae350", "-cpu", "andes-ax45mpv,vlen=512",
35	        "-nographic", "-semihosting-config", "enable=on,target=native", "-bios",
36	        "{elf}"}});
37	  return d;
38	}
39	
40	// A minimal engine descriptor for the resolution tests: only id + kind matter
41	// to resolve_accurate_engine.
42	EngineDescriptor eng(const std::string& id, const std::string& kind) {
43	  EngineDescriptor d;
44	  d.id = id;
45	  d.kind = kind;
46	  return d;
47	}
48	
49	}  // namespace
50	
51	int main() {
52	  const EngineDescriptor q = fake_qemu();
53	
54	  // The F7 done-when shape: post-`--` engine args (here a gdbstub) append
55	  // verbatim AFTER the filled standalone template.
56	  {
57	    std::string err;
58	    std::vector<std::string> got = passthrough_argv(
59	        q, "standalone", "/prog.elf", {"-gdb", "tcp::1234", "-S"}, err);
60	    CHECK(err.empty());
61	    check_eq(got,
62	             {"/q", "-machine", "andes_ae350", "-cpu", "andes-ax45mpv,vlen=512",
63	              "-nographic", "-semihosting-config", "enable=on,target=native",
64	              "-bios", "/prog.elf", "-gdb", "tcp::1234", "-S"},
65	             "gdbstub");
66	  }
67	
68	  // No passthrough args: just the filled template, {elf} in place.
69	  {
70	    std::string err;
71	    std::vector<std::string> got =
72	        passthrough_argv(q, "standalone", "/prog.elf", {}, err);
73	    CHECK(err.empty());
74	    check_eq(got,
75	             {"/q", "-machine", "andes_ae350", "-cpu", "andes-ax45mpv,vlen=512",
76	              "-nographic", "-semihosting-config", "enable=on,target=native",
77	              "-bios", "/prog.elf"},
78	             "no-pass");
79	  }
80	
81	  // A role the engine has no template for is an error, not a silent partial
82	  // argv (the caller must not spawn a half-built command line).
83	  {
84	    std::string err;
85	    std::vector<std::string> got =
86	        passthrough_argv(q, "accurate-leg", "/prog.elf", {}, err);
87	    CHECK(got.empty());
88	    CHECK(!err.empty());
89	  }
90	
91	  // --- resolve_accurate_engine (F8): which cycle-accurate engine `cycle` runs ---
92	  const EngineDescriptor qemu = eng("qemu", "functional");
93	  const EngineDescriptor v1 = eng("vsim:ax45mpv_premium", "cycle-accurate");
94	  const EngineDescriptor v2 = eng("vsim:ax66_makatau", "cycle-accurate");
95	
96	  // No --engine, exactly one cycle-accurate engine: that one is the default.
97	  {
98	    std::vector<EngineDescriptor> engines = {qemu, v1};
99	    std::string err;
100	    const EngineDescriptor* got = resolve_accurate_engine(engines, "", err);
101	    CHECK(got == &engines[1]);
102	    CHECK(err.empty());
103	  }
104	  // No --engine, two cycle-accurate engines: ambiguous -> error naming both.
105	  {
106	    std::vector<EngineDescriptor> engines = {qemu, v1, v2};
107	    std::string err;
108	    CHECK(resolve_accurate_engine(engines, "", err) == nullptr);
109	    CHECK(err.find("multiple") != std::string::npos);
110	    CHECK(err.find("vsim:ax45mpv_premium") != std::string::npos);
111	    CHECK(err.find("vsim:ax66_makatau") != std::string::npos);
112	  }
113	  // No --engine, zero cycle-accurate engines (qemu is functional): error.
114	  {
115	    std::vector<EngineDescriptor> engines = {qemu};
116	    std::string err;
117	    CHECK(resolve_accurate_engine(engines, "", err) == nullptr);
118	    CHECK(!err.empty());
119	  }
120	  // Explicit --engine selects that engine among several cycle-accurate ones.
121	  {
122	    std::vector<EngineDescriptor> engines = {qemu, v1, v2};
123	    std::string err;
124	    const EngineDescriptor* got =
125	        resolve_accurate_engine(engines, "vsim:ax66_makatau", err);
126	    CHECK(got == &engines[2]);
127	    CHECK(err.empty());
128	  }
129	  // Explicit --engine that matches no discovered engine: error.
130	  {
131	    std::vector<EngineDescriptor> engines = {qemu, v1};
132	    std::string err;
133	    CHECK(resolve_accurate_engine(engines, "vsim:nope", err) == nullptr);
134	    CHECK(err.find("vsim:nope") != std::string::npos);
135	  }
136	  // Explicit --engine naming a functional engine (qemu): wrong kind -> error.
137	  {
138	    std::vector<EngineDescriptor> engines = {qemu, v1};
139	    std::string err;
140	    CHECK(resolve_accurate_engine(engines, "qemu", err) == nullptr);
141	    CHECK(err.find("cycle-accurate") != std::string::npos);
142	  }
143	
144	  // --- normalize_engine_label: the vsim binary self-reports the third-party
145	  // simulator name; the product surface speaks "vsim". One translation point so
146	  // every downstream consumer (list / --engine / errors / banner) sees the
147	  // product id.
148	  {  // the legacy label is rewritten in both type and the id prefix
149	    EngineDescriptor d = eng("verilator:ax45mpv_premium", "cycle-accurate");
150	    d.type = "verilator";
151	    normalize_engine_label(d);
152	    CHECK(d.type == "vsim");
153	    CHECK(d.id == "vsim:ax45mpv_premium");
154	  }
155	  {  // the built-in functional engine is untouched
156	    EngineDescriptor d = eng("qemu", "functional");
157	    d.type = "qemu";
158	    normalize_engine_label(d);
159	    CHECK(d.type == "qemu");
160	    CHECK(d.id == "qemu");
161	  }
162	  {  // a different backend passes through verbatim (only verilator is renamed)
163	    EngineDescriptor d = eng("alioth:x", "cycle-accurate");
164	    d.type = "alioth";
165	    normalize_engine_label(d);
166	    CHECK(d.type == "alioth");
167	    CHECK(d.id == "alioth:x");
168	  }
169	
170	  return andes_sim::test::report("run");
171	}
