// `andesim list fixtures|models|engines`.
//
// `list fixtures` parses tests/fixtures/Makefile. `list models` is the
// composition axis that replaced the old `--mode`. `list engines` discovers
// engines at runtime via the F2 registry (`--describe`).
#include <algorithm>
#include <cstdio>
#include <filesystem>
#include <fstream>
#include <set>
#include <sstream>
#include <string>
#include <vector>

#include "cli.hpp"
#include "dev_mode.hpp"
#include "engine_registry.hpp"
#include "models.hpp"
#include "repo_root.hpp"
#include "strutil.hpp"

namespace fs = std::filesystem;

namespace andes_sim {
namespace {

std::vector<std::string> read_lines(const fs::path& p, bool& ok) {
  std::ifstream f(p);
  std::vector<std::string> lines;
  ok = static_cast<bool>(f);
  if (!ok) return lines;
  std::string line;
  while (std::getline(f, line)) lines.push_back(line);
  return lines;
}

// Match a Makefile variable assignment at column 0: `VAR :?= <body>` where
// VAR is [A-Z_][A-Z0-9_]*. Mirrors the Python regex anchor. On success sets
// `var` and `body` (the text after `=`, continuation backslash included).
bool parse_assignment(const std::string& line, std::string& var,
                      std::string& body) {
  const size_t n = line.size();
  if (n == 0) return false;
  char c0 = line[0];
  if (!((c0 >= 'A' && c0 <= 'Z') || c0 == '_')) return false;
  size_t p = 0;
  while (p < n) {
    char c = line[p];
    if ((c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_') ++p;
    else break;
  }
  var = line.substr(0, p);
  while (p < n && (line[p] == ' ' || line[p] == '\t')) ++p;  // \s*
  if (p < n && line[p] == ':') ++p;                          // :?
  if (p >= n || line[p] != '=') return false;                // =
  ++p;
  body = line.substr(p);
  return true;
}

struct Fixture {
  std::string name;
  std::string family;
};

// Extract fixture (name, family) rows from tests/fixtures/Makefile in stable,
// family-grouped, file order; dedupe globally; append handoff_roundtrip last.
std::vector<Fixture> parse_fixtures(const std::vector<std::string>& lines) {
  static const std::pair<std::string, std::string> interesting[] = {
      {"RT_FIXTURES", "asm"},
      {"RT_C_FIXTURES", "c"},
      {"RT_C_V_FIXTURES", "c+rvv"},
      {"PROBE_V_FIXTURES", "probe"},
  };
  std::vector<Fixture> rows;
  std::set<std::string> seen;

  for (size_t k = 0; k < lines.size(); ++k) {
    std::string var, body;
    if (!parse_assignment(lines[k], var, body)) continue;
    std::string family;
    for (const auto& it : interesting)
      if (it.first == var) { family = it.second; break; }
    if (family.empty()) continue;

    // Splice continuation lines: a trailing backslash + newline becomes a space.
    size_t li = k;
    while (!body.empty() && body.back() == '\\') {
      body.pop_back();
      body.push_back(' ');
      if (++li < lines.size()) body += lines[li];
      else break;
    }

    std::istringstream iss(body);
    std::string name;
    while (iss >> name)
      if (seen.insert(name).second) rows.push_back({name, family});
  }

  // handoff_roundtrip is not in a *_FIXTURES var; list it explicitly.
  if (seen.insert("handoff_roundtrip").second)
    rows.push_back({"handoff_roundtrip", "asm"});

  return rows;
}

int list_fixtures() {
  fs::path mk = repo_root() / "tests" / "fixtures" / "Makefile";
  bool ok;
  std::vector<std::string> lines = read_lines(mk, ok);
  if (!ok) {
    std::fprintf(stderr, "andesim: missing %s\n", mk.c_str());
    return 2;
  }
  std::vector<Fixture> rows = parse_fixtures(lines);

  size_t width = 0;
  for (const Fixture& r : rows) width = std::max(width, r.name.size());

  std::printf("%s  FAMILY\n", ljust("FIXTURE", width).c_str());
  for (const Fixture& r : rows)
    std::printf("%s  %s\n", ljust(r.name, width).c_str(), r.family.c_str());
  return 0;
}

int list_models() {
  size_t wn = 5, we = 7;  // header widths: MODEL, ENGINES
  for (const Model& m : kModels) {
    wn = std::max(wn, m.name.size());
    we = std::max(we, m.engines.size());
  }
  std::printf("%s  %s  NOTES\n", ljust("MODEL", wn).c_str(),
              ljust("ENGINES", we).c_str());
  for (const Model& m : kModels)
    std::printf("%s  %s  %s\n", ljust(std::string(m.name), wn).c_str(),
                ljust(std::string(m.engines), we).c_str(),
                std::string(m.notes).c_str());
  return 0;
}

int list_engines() {
  Discovery disc = discover_engines();

  // Columns describe engine identity only. Triggers are a hybrid-MODEL option
  // (see `list models` / `run --help`), not an engine attribute, so no TRIGGERS
  // column here.
  size_t we = 6, wt = 4, wk = 4;  // ENGINE, TYPE, KIND headers
  for (const EngineDescriptor& e : disc.engines) {
    we = std::max(we, e.id.size());
    wt = std::max(wt, e.type.size());
    wk = std::max(wk, e.kind.size());
  }

  // Hardware params from each engine's --describe; "-" = not reported.
  std::printf("%s  %s  %s  XLEN  VLEN  DLEN  ELEN\n",
              ljust("ENGINE", we).c_str(), ljust("TYPE", wt).c_str(),
              ljust("KIND", wk).c_str());
  for (const EngineDescriptor& e : disc.engines)
    std::printf("%s  %s  %s  %-4s  %-4s  %-4s  %-4s\n", ljust(e.id, we).c_str(),
                ljust(e.type, wt).c_str(), ljust(e.kind, wk).c_str(),
                vlen_str(e.xlen).c_str(), vlen_str(e.vlen).c_str(),
                vlen_str(e.dlen).c_str(), vlen_str(e.elen).c_str());

  // Binaries that could not self-describe are reported, never silently dropped.
  for (const std::string& w : disc.warnings)
    std::fprintf(stderr, "andesim: skipped engine: %s\n", w.c_str());
  return 0;
}

}  // namespace

int cmd_list(const Cli& cli) {
  // `fixtures` lists internal test ELFs -- a developer target, gated behind
  // ANDESIM_DEV so the release product offers only user-facing models/engines.
  const char* targets = is_dev_mode() ? "fixtures|models|engines" : "models|engines";
  if (cli.positional.empty()) {
    std::fprintf(stderr, "andesim list: expected one of %s\n", targets);
    return 2;
  }
  const std::string& t = cli.positional[0];
  if (t == "fixtures" && is_dev_mode()) return list_fixtures();
  if (t == "models") return list_models();
  if (t == "engines") return list_engines();
  std::fprintf(stderr, "andesim list: unknown target '%s' (want %s)\n",
               t.c_str(), targets);
  return 2;
}

}  // namespace andes_sim

// Shared-mmap allocation for andesim.
//
// The caller asks for `size` bytes; we resolve a backing directory over a
// tier list (first fit wins, fit = size + 256 MiB free), allocate a sparse
// file with mkstemp+truncate, and print one status line that always names
// the chosen tier -- and, when we fell past /dev/shm, why. HSIM_MMAP_DIR
// pins a single tier (hard error if it does not fit; no fallback past it).
#ifndef ANDESIM_SHM_HPP
#define ANDESIM_SHM_HPP

#include <functional>
#include <string>
#include <vector>

namespace andes_sim {

// Free-space headroom a tier must have beyond the requested size.
inline constexpr long long kMmapSafetyMargin = 256LL * 1024 * 1024;

// One backing-store candidate: the directory plus the label used in
// status/error messages ("/dev/shm", "~/.cache/andesim", "HSIM_MMAP_DIR=..").
struct MmapTier {
  std::string dir;
  std::string label;
};

// resolve_mmap_dir result: the chosen dir ("" on failure) and, when a tier
// was skipped, a human note saying which and why ("" when tiers[0] fit).
struct MmapDirChoice {
  std::string dir;
  std::string note;
};

// Parse "8G" / "512M" / "1024" / "1.5G" into a positive byte count. On success
// returns the count and leaves `err` empty; on failure returns 0 and sets `err`
// to the argparse-style message. Fractional values truncate (1.5G -> whole
// bytes).
long long parse_size(const std::string& spec, std::string& err);

// L26/F2: the physical shared mmap is one V-scratch page (HYBRID_V_SCRATCH_BYTES)
// larger than the program's --mem-size, so the V-register transport page sits
// just ABOVE the program's declared RAM. No program layout -- low stack, top-of-
// RAM stack, or a heap grown to the ceiling -- can reach a page past its own
// RAM, so the scratch can never be clobbered. The vsim side parks the scratch
// at the mmap's top page (v_scratch_gpa), which equals ram_base + program_bytes.
long long physical_mmap_bytes(long long program_bytes);

// The largest --mem-size whose physical mmap still fits the 2 GiB AE350 DRAM
// window (program_bytes + scratch page <= 2 GiB). --mem-size is capped here.
long long max_program_mem_bytes();

// First-fit resolver over `tiers`. `probe(dir)` returns the dir's free bytes,
// or -1 when it does not exist. A tier fits when probe >= size + margin.
// On success `err` is empty; when nothing fits, returns {"", ""} and `err`
// names every tier's reason plus the HSIM_MMAP_DIR hint. Pure: no env, no
// filesystem -- testable with a fake probe.
MmapDirChoice resolve_mmap_dir(
    const std::vector<MmapTier>& tiers, long long size,
    const std::function<long long(const std::string&)>& probe,
    std::string& err);

// The andesim cache root: $XDG_CACHE_HOME/andesim, else ~/.cache/andesim,
// else "" (no HOME). Shared by the mmap tier list and the repro bundles.
std::string andesim_cache_dir();

// Build the real tier list from the environment:
//   HSIM_MMAP_DIR set -> that single pinned tier;
//   else            -> /dev/shm, then $XDG_CACHE_HOME|~/.cache + /andesim
//                      (created here so the free-space probe can see it).
std::vector<MmapTier> mmap_tiers();

// WSL2 advice for `doctor`: given /proc/version contents, the repo dir, and
// the mmap tier list, return warning lines. Empty when not on WSL2. On WSL2:
// always the .wslconfig memory= hint (tmpfs is capped by the WSL VM), plus a
// drvfs warning for the repo or any tier dir under /mnt/ (slow, and
// MAP_SHARED is not coherent across the 9p boundary). Pure -- testable.
std::vector<std::string> wsl_warnings(const std::string& proc_version,
                                      const std::string& repo_dir,
                                      const std::vector<MmapTier>& tiers);

// Convert a --mem-size spec into the fast leg's plain QEMU `-m` argv:
// {"-m", "<MiB>M"}. Empty spec -> {} with no error (QEMU as-is). Malformed
// specs and sizes that are not a whole MiB (QEMU's -m granularity) return {}
// and set `err`.
std::vector<std::string> qemu_m_args(const std::string& spec, std::string& err);

// Allocate a sparse mmap file of `size` bytes in the resolved dir (mkstemp +
// truncate), print one "[hsim mmap] <size> at <dir> (free: <free>)" line
// (plus "; fallback: <why>" when /dev/shm was skipped), and return its path.
// On failure returns "" and sets `err`. Caller owns the file (unlink when
// done).
std::string allocate(long long size, std::string& err,
                     const std::string& prefix = "hsim-shm.");

}  // namespace andes_sim

#endif  // ANDESIM_SHM_HPP

